<script setup lang="ts">import {onMounted,ref} from 'vue'; import {api} from '../api'; const data=ref<Record<string,number>>({}); const error=ref(''); onMounted(async()=>{try{data.value=(await api.get('/dashboard')).data}catch(e){error.value='无法连接 API。请启动 docker compose。'}});</script><template><h1>监管驾驶舱</h1><el-alert v-if="error" :title="error" type="warning"/><el-row :gutter="16"><el-col v-for="(v,k) in data" :key="k" :span="6"><el-card><div class="k">{{k}}</div><strong>{{v}}</strong></el-card></el-col></el-row><el-card><h3>合规监控</h3><p>实时关注在途配送、验收异常、临期库存、待结算账款；批次可通过库存编号进入追溯接口。</p></el-card></template><style scoped>.el-card{margin:8px 0}.k{color:#718096;text-transform:capitalize}strong{font-size:32px;color:#2f6fed}</style>
